# Blit a digit (0-9) into a framebuf.FrameBuffer at (x,y) in RGB565 mode.
def draw_digit(fb, d, x, y, color):
    glyph = DIGITS[d]
    w, h = fb.width, fb.height
    for row in range(48):
        row_bits = (glyph[row*4] << 24) | (glyph[row*4 + 1] << 16) | (glyph[row*4 + 2] << 8) | glyph[row*4 + 3]
        for col in range(32):
            if row_bits & (1 << (31 - col)):
                px = x + col
                py = y + row
                if 0 <= px < w and 0 <= py < h:
                    fb.pixel(px, py, color)

def _text_width(s):
    total_w = 0
    for ch in s:
        if ch == '.':
            total_w += 8
        elif ch == ' ':
            total_w += 32
        elif ch.isdigit():
            total_w += 32
    return total_w

def draw_number(fb, s, x, y, color):
    x_pos = x
    for ch in s:
        if ch == '.':
            fb.fill_rect(x_pos - 2, y + 40, 4, 4, color)
            x_pos += 8
        elif ch == ' ':
            # skip leading spaces; draw nothing
            x_pos += 32
        elif ch.isdigit():
            draw_digit(fb, int(ch), x_pos, y, color)
            x_pos += 32

def draw_number_right(fb, s, x_end, y, color):
    total_w = _text_width(s)
    draw_number(fb, s, x_end - total_w, y, color)

def draw_number_trimmed(fb, s, x, y, color):
    """Draw number string without leading spaces, useful when left-aligning."""
    draw_number(fb, s.lstrip(), x, y, color)
